import XCTest
@testable import ZeroInCore

/// Tests for DragTables, the Atmosphere physics extension and BallisticSolver.
///
/// The reference vectors at the bottom of this file are generated by
/// `tools/ballistics_reference.py --update-swift`:
/// - `ref*` values come from py-ballisticcalc (independent RK4 solver) and are checked
///   with the physics tolerances: path max(0.5 in, 1.5 %), drift max(0.5 in, 3 %),
///   velocity 1 %, at every range ≤ 800 yd.
/// - `port*` values come from the Python line-by-line port of this solver and are
///   checked tightly over the full 0–1000 yd, so any Swift/Python divergence shows up.
final class BallisticsTests: XCTestCase {

    // MARK: - Fixtures

    private let smk308 = Projectile(bc: 0.462, dragModel: .g1, weightGrains: 168,
                                    diameterInches: 0.308, muzzleVelocityFPS: 2650)
    private let lr22 = Projectile(bc: 0.138, dragModel: .g1, weightGrains: 40,
                                  diameterInches: 0.223, muzzleVelocityFPS: 1080)
    private let wm300 = Projectile(bc: 0.507, dragModel: .g1, weightGrains: 180,
                                   diameterInches: 0.308, muzzleVelocityFPS: 2960)
    private let magnum3500 = Projectile(bc: 0.400, dragModel: .g1, weightGrains: 150,
                                        diameterInches: 0.308, muzzleVelocityFPS: 3500)
    private let scope100 = ScopeSpec(clickValue: 0.25, clickUnit: .moa, sightHeightInches: 1.5, zeroRangeYards: 100)

    // MARK: - DragTables

    func testDragTablesExactRows() {
        XCTAssertEqual(DragTables.dragCoefficient(.g1, mach: 0.0), 0.2629, accuracy: 1e-12)
        XCTAssertEqual(DragTables.dragCoefficient(.g1, mach: 1.0), 0.4805, accuracy: 1e-12)
        XCTAssertEqual(DragTables.dragCoefficient(.g1, mach: 1.4), 0.6625, accuracy: 1e-12)
        XCTAssertEqual(DragTables.dragCoefficient(.g7, mach: 1.0), 0.3803, accuracy: 1e-12)
        XCTAssertEqual(DragTables.dragCoefficient(.g7, mach: 1.05), 0.4043, accuracy: 1e-12)
        XCTAssertEqual(DragTables.dragCoefficient(.g7, mach: 2.0), 0.2980, accuracy: 1e-12)
    }

    func testDragTablesLinearInterpolation() {
        // Midway between G1 rows 0.6 (0.2034) and 0.7 (0.2165).
        XCTAssertEqual(DragTables.dragCoefficient(.g1, mach: 0.65), (0.2034 + 0.2165) / 2, accuracy: 1e-12)
        // A quarter of the way between G1 rows 2.5 (0.5397) and 2.6 (0.5325).
        XCTAssertEqual(DragTables.dragCoefficient(.g1, mach: 2.525), 0.5397 + 0.25 * (0.5325 - 0.5397), accuracy: 1e-12)
        // Midway between G7 rows 0.9 (0.1464) and 0.925 (0.1660).
        XCTAssertEqual(DragTables.dragCoefficient(.g7, mach: 0.9125), (0.1464 + 0.1660) / 2, accuracy: 1e-12)
    }

    func testDragTablesClampAtEnds() {
        XCTAssertEqual(DragTables.dragCoefficient(.g1, mach: -1), 0.2629, accuracy: 1e-12)
        XCTAssertEqual(DragTables.dragCoefficient(.g1, mach: 10), 0.4988, accuracy: 1e-12)
        XCTAssertEqual(DragTables.dragCoefficient(.g7, mach: -0.5), 0.1198, accuracy: 1e-12)
        XCTAssertEqual(DragTables.dragCoefficient(.g7, mach: 6), 0.1618, accuracy: 1e-12)
        XCTAssertEqual(DragTables.dragCoefficient(.g7, mach: .nan), 0.1198, accuracy: 1e-12)
    }

    func testDragTablesShape() {
        for model in DragModel.allCases {
            let t = DragTables.table(for: model)
            XCTAssertEqual(t.mach.count, t.cd.count)
            XCTAssertEqual(t.mach.count, model == .g1 ? 79 : 84)
            for i in 1..<t.mach.count {
                XCTAssertGreaterThan(t.mach[i], t.mach[i - 1], "\(model) Mach not increasing at row \(i)")
            }
        }
        // Transonic rise: drag peaks above Mach 1 for both models.
        XCTAssertGreaterThan(DragTables.dragCoefficient(.g1, mach: 1.3), DragTables.dragCoefficient(.g1, mach: 0.8))
        XCTAssertGreaterThan(DragTables.dragCoefficient(.g7, mach: 1.05), DragTables.dragCoefficient(.g7, mach: 0.8))
    }

    // MARK: - Atmosphere

    func testStandardDensityRatioIsOne() {
        XCTAssertEqual(Atmosphere.standard.densityRatio, 1.0, accuracy: 1e-12)
    }

    func testDensityRatioAt5000FeetStandard() {
        let ratio = Atmosphere.standard(atAltitudeFeet: 5000).densityRatio
        XCTAssertEqual(ratio, 0.8617, accuracy: 0.005)
    }

    func testDensityRatioTemperatureAndHumidity() {
        let cold = Atmosphere(temperatureF: 20, pressureInHg: 29.92, humidityPercent: 0).densityRatio
        let hot = Atmosphere(temperatureF: 100, pressureInHg: 29.92, humidityPercent: 0).densityRatio
        let hotHumid = Atmosphere(temperatureF: 100, pressureInHg: 29.92, humidityPercent: 100).densityRatio
        XCTAssertGreaterThan(cold, 1.0)
        XCTAssertLessThan(hot, 1.0)
        XCTAssertLessThan(hotHumid, hot)  // water vapour is lighter than dry air
        XCTAssertEqual(hot - hotHumid, 0.0226, accuracy: 0.002)  // ~2.3 % at 100 °F saturated
        // Station pressure scales density linearly.
        XCTAssertEqual(Atmosphere(temperatureF: 59, pressureInHg: 24.0).densityRatio, 24.0 / 29.92, accuracy: 1e-12)
    }

    func testSpeedOfSound() {
        XCTAssertEqual(Atmosphere.standard.speedOfSoundFPS, 1116.45, accuracy: 0.05)
        XCTAssertEqual(Atmosphere(temperatureF: 32).speedOfSoundFPS, 49.0223 * (491.67).squareRoot(), accuracy: 1e-9)
        XCTAssertLessThan(Atmosphere(temperatureF: 0).speedOfSoundFPS, Atmosphere(temperatureF: 90).speedOfSoundFPS)
    }

    // MARK: - Zero

    func testZeroAngleIsPositiveAndSmall() {
        let solver = BallisticSolver(projectile: smk308, scope: scope100)
        let angle = solver.zeroAngleRadians()
        XCTAssertGreaterThan(angle, 0)
        XCTAssertEqual(angle * 10_800 / .pi, 3.918, accuracy: 0.02)  // MOA, matches py-ballisticcalc
    }

    func testZeroConvergesAcrossRangesAndVelocities() {
        let loads = [smk308, lr22, wm300, magnum3500]
        for load in loads {
            for zero in [10.0, 25, 50, 100, 200, 300, 500, 750, 1000] {
                let scope = ScopeSpec(sightHeightInches: 1.5, zeroRangeYards: zero)
                let solver = BallisticSolver(projectile: load, scope: scope)
                let angle = solver.zeroAngleRadians()
                XCTAssertTrue(angle.isFinite)
                XCTAssertGreaterThan(angle, 0, "v=\(load.muzzleVelocityFPS) zero=\(zero)")
                let path = solver.point(atYards: zero).pathInches
                XCTAssertEqual(path, 0, accuracy: 0.01, "v=\(load.muzzleVelocityFPS) zero=\(zero)")
            }
        }
    }

    func testZeroIgnoresWind() {
        let calm = BallisticSolver(projectile: smk308, scope: scope100)
        let windy = BallisticSolver(projectile: smk308, scope: scope100,
                                    conditions: ShotConditions(wind: WindCondition(speedMPH: 20, directionDegrees: 0)))
        XCTAssertEqual(calm.zeroAngleRadians(), windy.zeroAngleRadians(), accuracy: 1e-15)
    }

    // MARK: - Trajectory

    func testMuzzleRow() {
        let solver = BallisticSolver(projectile: smk308, scope: scope100)
        let rows = solver.trajectory(maxRangeYards: 100, stepYards: 25)
        XCTAssertEqual(rows.count, 5)
        let muzzle = rows[0]
        XCTAssertEqual(muzzle.rangeYards, 0, accuracy: 1e-12)
        XCTAssertEqual(muzzle.pathInches, -1.5, accuracy: 1e-12)
        XCTAssertEqual(muzzle.windageInches, 0, accuracy: 1e-12)
        XCTAssertEqual(muzzle.velocityFPS, 2650, accuracy: 1e-9)
        XCTAssertEqual(muzzle.timeSeconds, 0, accuracy: 1e-12)
        XCTAssertEqual(muzzle.dropFromBoreInches, 0, accuracy: 1e-12)
        XCTAssertEqual(muzzle.energyFtLb, Conversions.energyFtLb(grains: 168, fps: 2650), accuracy: 1e-9)
        XCTAssertEqual(muzzle.mach, 2650 / Atmosphere.standard.speedOfSoundFPS, accuracy: 1e-12)
        XCTAssertEqual(rows[4].pathInches, 0, accuracy: 0.01)  // the zero
    }

    func testTrajectoryRowsAreAtExactSteps() {
        let solver = BallisticSolver(projectile: smk308, scope: scope100)
        let rows = solver.trajectory(maxRangeYards: 250, stepYards: 50)
        XCTAssertEqual(rows.map(\.rangeYards), [0, 50, 100, 150, 200, 250])
        XCTAssertEqual(solver.trajectory(maxRangeYards: 1000, stepYards: 100).count, 11)
        XCTAssertEqual(solver.trajectory(maxRangeYards: 95, stepYards: 10).count, 10)  // 0…90
        // point(atYards:) agrees with the table row at the same range.
        let p = solver.point(atYards: 250)
        XCTAssertEqual(p.pathInches, rows[5].pathInches, accuracy: 1e-6)
        XCTAssertEqual(p.velocityFPS, rows[5].velocityFPS, accuracy: 1e-6)
        XCTAssertEqual(p.timeSeconds, rows[5].timeSeconds, accuracy: 1e-9)
    }

    func testTrajectoryIsMonotonicAndPhysical() {
        let solver = BallisticSolver(projectile: smk308, scope: scope100)
        let rows = solver.trajectory(maxRangeYards: 1000, stepYards: 50)
        for i in 1..<rows.count {
            XCTAssertLessThan(rows[i].velocityFPS, rows[i - 1].velocityFPS)
            XCTAssertGreaterThan(rows[i].timeSeconds, rows[i - 1].timeSeconds)
            XCTAssertLessThanOrEqual(rows[i].dropFromBoreInches, 0)
            XCTAssertEqual(rows[i].energyFtLb,
                           Conversions.energyFtLb(grains: 168, fps: rows[i].velocityFPS), accuracy: 1e-6)
            XCTAssertEqual(rows[i].mach, rows[i].velocityFPS / Atmosphere.standard.speedOfSoundFPS, accuracy: 1e-9)
        }
        // Rising above the LOS between the near and far zero, falling below beyond it.
        XCTAssertGreaterThan(rows[1].pathInches, -1.5)
        XCTAssertLessThan(rows[rows.count - 1].pathInches, -300)
    }

    func testInvalidTrajectoryInputs() {
        let solver = BallisticSolver(projectile: smk308, scope: scope100)
        XCTAssertTrue(solver.trajectory(maxRangeYards: 100, stepYards: 0).isEmpty)
        XCTAssertTrue(solver.trajectory(maxRangeYards: 100, stepYards: -5).isEmpty)
        XCTAssertTrue(solver.trajectory(maxRangeYards: -1, stepYards: 10).isEmpty)
        XCTAssertTrue(solver.trajectory(maxRangeYards: 100, stepYards: .nan).isEmpty)
        XCTAssertEqual(solver.trajectory(maxRangeYards: 0, stepYards: 10).count, 1)
        XCTAssertEqual(solver.point(atYards: -10).rangeYards, 0, accuracy: 1e-12)
    }

    func testTrajectoryStopsEarlyBelowFloor() {
        // A .22 LR falls below -5000 in well before 3000 yd.
        let scope = ScopeSpec(sightHeightInches: 1.5, zeroRangeYards: 50)
        let solver = BallisticSolver(projectile: lr22, scope: scope)
        let rows = solver.trajectory(maxRangeYards: 3000, stepYards: 100)
        XCTAssertLessThan(rows.count, 31)
        XCTAssertGreaterThan(rows.count, 10)
        XCTAssertGreaterThan(rows[rows.count - 1].pathInches, -5000)
    }

    func testWindSigns() {
        func drift(_ degrees: Double) -> Double {
            let c = ShotConditions(wind: WindCondition(speedMPH: 10, directionDegrees: degrees))
            return BallisticSolver(projectile: smk308, scope: scope100, conditions: c).point(atYards: 500).windageInches
        }
        XCTAssertLessThan(drift(90), -20)       // from 3 o'clock → pushed left
        XCTAssertGreaterThan(drift(270), 20)    // from 9 o'clock → pushed right
        XCTAssertEqual(drift(90), -drift(270), accuracy: 1e-9)
        XCTAssertEqual(drift(0), 0, accuracy: 1e-9)  // pure headwind
        // A headwind slows the bullet relative to the ground; a tailwind does the opposite.
        let head = BallisticSolver(projectile: smk308, scope: scope100,
                                   conditions: ShotConditions(wind: WindCondition(speedMPH: 20, directionDegrees: 0)))
        let tail = BallisticSolver(projectile: smk308, scope: scope100,
                                   conditions: ShotConditions(wind: WindCondition(speedMPH: 20, directionDegrees: 180)))
        XCTAssertLessThan(head.point(atYards: 800).pathInches, tail.point(atYards: 800).pathInches)
    }

    func testUphillShotPrintsHigherThanFlat() {
        let flat = BallisticSolver(projectile: smk308, scope: scope100)
        let up = BallisticSolver(projectile: smk308, scope: scope100, conditions: ShotConditions(inclinationDegrees: 10))
        let down = BallisticSolver(projectile: smk308, scope: scope100, conditions: ShotConditions(inclinationDegrees: -10))
        for yards in [500.0, 1000.0] {
            XCTAssertGreaterThan(up.point(atYards: yards).pathInches, flat.point(atYards: yards).pathInches)
            XCTAssertGreaterThan(down.point(atYards: yards).pathInches, flat.point(atYards: yards).pathInches)
        }
    }

    func testExpectedImpactAt25ForA100YardZero() {
        let solver = BallisticSolver(projectile: smk308, scope: scope100)
        let impact = solver.expectedImpact(atYards: 25)
        XCTAssertEqual(impact.x, 0, accuracy: 1e-12)
        XCTAssertLessThan(impact.y, -0.5)    // below the point of aim…
        XCTAssertGreaterThan(impact.y, -0.8)  // …by about 0.6 in
        XCTAssertEqual(impact.y, -0.631, accuracy: 0.01)
        // Same as the trajectory row.
        XCTAssertEqual(impact.y, solver.point(atYards: 25).pathInches, accuracy: 1e-12)
    }

    func testDeterministic() {
        let a = BallisticSolver(projectile: smk308, scope: scope100).trajectory(maxRangeYards: 600, stepYards: 50)
        let b = BallisticSolver(projectile: smk308, scope: scope100).trajectory(maxRangeYards: 600, stepYards: 50)
        XCTAssertEqual(a, b)
    }

    // MARK: - MPBR

    func testMaxPointBlankRange308() {
        let solver = BallisticSolver(projectile: smk308, scope: scope100)
        let mpbr = solver.maxPointBlankRange(vitalZoneInches: 6)
        let ref = ballisticReferenceMPBR
        XCTAssertEqual(mpbr.zeroRangeYards, ref.refZero, accuracy: max(1.0, 0.02 * ref.refZero))
        XCTAssertEqual(mpbr.maxRangeYards, ref.refMax, accuracy: max(1.0, 0.015 * ref.refMax))
        XCTAssertEqual(mpbr.zeroRangeYards, ref.portZero, accuracy: 0.05)
        XCTAssertEqual(mpbr.maxRangeYards, ref.portMax, accuracy: 0.05)

        // Re-zeroing at the MPBR zero keeps the path inside ±3 in out to the max range.
        let rezeroed = BallisticSolver(projectile: smk308,
                                       scope: ScopeSpec(sightHeightInches: 1.5, zeroRangeYards: mpbr.zeroRangeYards))
        let rows = rezeroed.trajectory(maxRangeYards: mpbr.maxRangeYards, stepYards: 1)
        let apex = rows.map(\.pathInches).max() ?? 0
        XCTAssertEqual(apex, 3.0, accuracy: 0.01)
        XCTAssertEqual(rezeroed.point(atYards: mpbr.maxRangeYards).pathInches, -3.0, accuracy: 0.01)
    }

    func testMaxPointBlankRangeSanity() {
        let solver = BallisticSolver(projectile: smk308, scope: scope100)
        let small = solver.maxPointBlankRange(vitalZoneInches: 4)
        let large = solver.maxPointBlankRange(vitalZoneInches: 8)
        XCTAssertLessThan(small.maxRangeYards, large.maxRangeYards)
        XCTAssertLessThan(small.zeroRangeYards, small.maxRangeYards)
        XCTAssertGreaterThan(small.zeroRangeYards, 100)
        let faster = BallisticSolver(projectile: wm300, scope: scope100).maxPointBlankRange(vitalZoneInches: 6)
        XCTAssertGreaterThan(faster.maxRangeYards, solver.maxPointBlankRange(vitalZoneInches: 6).maxRangeYards)
        let none = solver.maxPointBlankRange(vitalZoneInches: 0)
        XCTAssertEqual(none.zeroRangeYards, 0)
        XCTAssertEqual(none.maxRangeYards, 0)
    }

    // MARK: - Performance

    func testThousandYardTrajectoryIsFast() {
        let solver = BallisticSolver(projectile: lr22, scope: ScopeSpec(sightHeightInches: 1.5, zeroRangeYards: 50))
        let start = Date()
        let rows = solver.trajectory(maxRangeYards: 1000, stepYards: 1)
        let elapsed = Date().timeIntervalSince(start)
        XCTAssertEqual(rows.count, 1001)
        // Generous bound so unoptimised debug builds on CI pass; release on device is ~1 ms.
        XCTAssertLessThan(elapsed, 0.5)
        measure {
            _ = BallisticSolver(projectile: self.smk308, scope: self.scope100).trajectory(maxRangeYards: 1000, stepYards: 25)
        }
    }

    // MARK: - Reference vectors (py-ballisticcalc + Python port)

    func testReferenceVectors() {
        XCTAssertFalse(ballisticReferenceCases.isEmpty)
        for c in ballisticReferenceCases {
            let projectile = Projectile(bc: c.bc, dragModel: c.model, weightGrains: c.weightGrains,
                                        diameterInches: c.diameterInches, muzzleVelocityFPS: c.muzzleVelocityFPS)
            let scope = ScopeSpec(sightHeightInches: c.sightHeightInches, zeroRangeYards: c.zeroRangeYards)
            let atmosphere = Atmosphere(altitudeFeet: c.altitudeFeet, temperatureF: c.temperatureF,
                                        pressureInHg: c.pressureInHg, humidityPercent: c.humidityPercent)
            let conditions = ShotConditions(atmosphere: atmosphere,
                                            wind: WindCondition(speedMPH: c.windMPH, directionDegrees: c.windDegrees),
                                            inclinationDegrees: c.inclinationDegrees)
            let solver = BallisticSolver(projectile: projectile, scope: scope, conditions: conditions)

            let zero = solver.zeroAngleRadians()
            XCTAssertEqual(zero, c.refZeroAngle, accuracy: max(2e-6, 0.01 * abs(c.refZeroAngle)), "\(c.name) zero vs ref")
            XCTAssertEqual(zero, c.portZeroAngle, accuracy: 1e-7, "\(c.name) zero vs port")

            let rows = solver.trajectory(maxRangeYards: 1000, stepYards: 100)
            XCTAssertEqual(rows.count, c.rows.count, "\(c.name) row count")
            for (row, ref) in zip(rows, c.rows) {
                let label = "\(c.name) @ \(Int(ref.yards)) yd"
                XCTAssertEqual(row.rangeYards, ref.yards, accuracy: 1e-9, label)
                if ref.yards <= 800 {
                    XCTAssertEqual(row.pathInches, ref.refPath,
                                   accuracy: max(0.5, 0.015 * abs(ref.refPath)), "\(label) path vs ref")
                    XCTAssertEqual(row.windageInches, ref.refWindage,
                                   accuracy: max(0.5, 0.03 * abs(ref.refWindage)), "\(label) drift vs ref")
                    XCTAssertEqual(row.velocityFPS, ref.refVelocity,
                                   accuracy: 0.01 * ref.refVelocity, "\(label) velocity vs ref")
                }
                XCTAssertEqual(row.pathInches, ref.portPath, accuracy: 0.02, "\(label) path vs port")
                XCTAssertEqual(row.windageInches, ref.portWindage, accuracy: 0.02, "\(label) drift vs port")
                XCTAssertEqual(row.velocityFPS, ref.portVelocity, accuracy: 0.05, "\(label) velocity vs port")
            }
        }
    }
}

// MARK: - Reference vector types

private struct BallisticReferenceRow: Sendable {
    let yards: Double
    let refPath: Double
    let refWindage: Double
    let refVelocity: Double
    let portPath: Double
    let portWindage: Double
    let portVelocity: Double
}

private struct BallisticReferenceCase: Sendable {
    let name: String
    let bc: Double
    let model: DragModel
    let weightGrains: Double
    let diameterInches: Double
    let muzzleVelocityFPS: Double
    let sightHeightInches: Double
    let zeroRangeYards: Double
    let altitudeFeet: Double
    let temperatureF: Double
    let pressureInHg: Double
    let humidityPercent: Double
    let windMPH: Double
    let windDegrees: Double
    let inclinationDegrees: Double
    let refZeroAngle: Double
    let portZeroAngle: Double
    let rows: [BallisticReferenceRow]
}

private struct BallisticReferenceMPBR: Sendable {
    let refZero: Double
    let refMax: Double
    let portZero: Double
    let portMax: Double
}

